export default docs;
declare const docs: "Shows a table of contents built from the headings on the page, so readers can jump to a section.\n\nIt reads the headings of the page's text blocks when it renders, so it needs no content of its own. Its settings (title, heading levels, ordered list) are optional.\n\n### Example\n\n```json\n{ \"@type\": \"toc\" }\n```\n";
